import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type Job, type JobRow } from './db.ts';
import { validateSubmission, type FieldError } from './validation.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** The worker counts as up if its heartbeat is at most this old. */
const WORKER_FRESH_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  const error = code === 'invalid_request' ? { code, message, fields: fields ?? [] } : { code, message };
  sendJson(res, status, { error }, headers);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function selectJobById(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const errors: FieldError[] = [];

  // Node joins repeated headers with ", " for these names, so a duplicated header fails the pattern.
  const keyHeader = req.headers['idempotency-key'];
  const key = Array.isArray(keyHeader) ? keyHeader.join(', ') : keyHeader;
  if (key !== undefined && !IDEMPOTENCY_KEY.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'must be 1 to 128 characters: letters, digits, "_" or "-"' });
  }

  const typeHeader = req.headers['content-type'];
  const contentType = (Array.isArray(typeHeader) ? typeHeader.join(', ') : (typeHeader ?? '')).trim();
  if (!/^application\/json\s*(;|$)/i.test(contentType)) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  }

  const { text, tooLarge } = await readBody(req);
  let body: Record<string, unknown> | undefined;
  if (tooLarge) {
    errors.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(text);
    } catch {
      errors.push({ field: 'body', message: 'malformed JSON' });
    }
    if (parsed !== undefined) {
      if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
        body = parsed as Record<string, unknown>;
      } else {
        errors.push({ field: 'body', message: 'must be a JSON object' });
      }
    }
  }

  const submission = body ? validateSubmission(body, errors) : undefined;
  if (errors.length > 0 || !submission) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', errors);
    return;
  }

  // Check-then-insert runs in one IMMEDIATE transaction so the worker cannot interleave a write.
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        const same =
          existing.input === submission.input &&
          existing.steps === submission.steps &&
          existing.fail_attempts === submission.failAttempts;
        if (same) sendJson(res, 200, toJob(existing));
        else sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        return;
      }
    }

    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?)`,
    ).run(id, submission.input, submission.steps, submission.failAttempts, key ?? null, now, now);
    const row = selectJobById(id);
    db.exec('COMMIT');
    if (!row) throw new Error(`job ${id} missing after insert`);
    sendJson(res, 201, toJob(row));
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

function handleList(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  const jobs: Job[] = rows.map(toJob);
  sendJson(res, 200, { jobs });
}

function handleGet(res: ServerResponse, id: string): void {
  const row = selectJobById(id);
  if (!row) {
    sendError(res, 404, 'not_found', `No job with id ${id}.`);
    return;
  }
  sendJson(res, 200, toJob(row));
}

function handleHealth(res: ServerResponse): void {
  const row = db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'").get() as unknown as { at: number } | undefined;
  const up = row !== undefined && Date.now() - row.at <= WORKER_FRESH_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allow}.`, undefined, { allow });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return handleHealth(res);
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleList(res);
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'Not found.');
    }
    return handleGet(res, id);
  }
  sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 2_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

