import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 100;
const HEARTBEAT_MS = 1_000;
const MAX_ATTEMPTS = 3;
/** Retry delay is drawn from [RETRY_MIN_MS, RETRY_MIN_MS + RETRY_SPREAD_MS], kept under 2 s even with polling overshoot. */
const RETRY_MIN_MS = 250;
const RETRY_SPREAD_MS = 1_250;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const now = (): string => new Date().toISOString();

function heartbeat(): void {
  db.prepare(
    "INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at",
  ).run(Date.now());
}

/**
 * Records a failed attempt `attempt` (already stored as the job's attempts value). Requeues the job
 * after a delay, or marks it failed once MAX_ATTEMPTS have failed.
 */
function recordFailedAttempt(id: string, attempt: number): void {
  if (attempt >= MAX_ATTEMPTS) {
    db.prepare(
      `UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL,
         progress_completed = 0, next_run_at = NULL, updated_at = ? WHERE id = ?`,
    ).run(now(), id);
    return;
  }
  const delay = RETRY_MIN_MS + Math.floor(Math.random() * (RETRY_SPREAD_MS + 1));
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, next_run_at = ?, updated_at = ? WHERE id = ?`,
  ).run(Date.now() + delay, now(), id);
}

/**
 * A job left `running` means the worker died mid-attempt. Failing attempts are recorded in one
 * step, so a `running` job with attempts <= failAttempts was a failing attempt that was cut short:
 * record it as failed. Otherwise the attempt was succeeding and is simply requeued.
 */
function recoverInterruptedJobs(): void {
  db.exec('BEGIN IMMEDIATE');
  try {
    const rows = db.prepare("SELECT * FROM jobs WHERE status = 'running'").all() as unknown as JobRow[];
    for (const job of rows) {
      if (job.attempts <= job.fail_attempts) recordFailedAttempt(job.id, job.attempts);
      else db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, updated_at = ? WHERE id = ?").run(now(), job.id);
    }
    db.exec('COMMIT');
    if (rows.length > 0) console.log(`recovered ${rows.length} interrupted job(s)`);
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

function nextQueuedJob(): JobRow | undefined {
  return db
    .prepare(
      `SELECT * FROM jobs WHERE status = 'queued' AND (next_run_at IS NULL OR next_run_at <= ?)
       ORDER BY seq LIMIT 1`,
    )
    .get(Date.now()) as unknown as JobRow | undefined;
}

async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts + 1;
  db.prepare(
    "UPDATE jobs SET status = 'running', attempts = ?, progress_completed = 0, next_run_at = NULL, updated_at = ? WHERE id = ?",
  ).run(attempt, now(), job.id);

  if (attempt <= job.fail_attempts) {
    recordFailedAttempt(job.id, attempt);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return; // stays `running`; recovered on the next start
    db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?').run(step, now(), job.id);
  }
  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, progress_completed = ?, updated_at = ? WHERE id = ?",
  ).run(job.input.toUpperCase(), job.steps, now(), job.id);
}

recoverInterruptedJobs();
heartbeat();
const heartbeatTimer = setInterval(() => {
  try {
    heartbeat();
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    const job = nextQueuedJob();
    if (job) await processJob(job);
    else await sleep(POLL_MS);
  } catch (e) {
    console.error('worker iteration failed:', e);
    await sleep(500);
  }
}

clearInterval(heartbeatTimer);
try {
  db.prepare("DELETE FROM heartbeats WHERE name = 'worker'").run();
} finally {
  db.close();
}
process.exit(0);

