export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;
const MAX_INPUT_LENGTH = 1000;

function intField(body: Record<string, unknown>, name: string, def: number, min: number, max: number, errors: FieldError[]): number | undefined {
  if (!Object.hasOwn(body, name)) return def;
  const value = body[name];
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return undefined;
  }
  return value;
}

/**
 * Validates a submission body that is already a JSON object. Appends one entry per problem to
 * `errors` and returns the normalised submission (defaults applied) only when there are none.
 */
export function validateSubmission(body: Record<string, unknown>, errors: FieldError[]): Submission | undefined {
  const before = errors.length;
  for (const key of Object.keys(body)) {
    if (!KNOWN_FIELDS.has(key)) errors.push({ field: key, message: 'unknown field' });
  }

  let input: string | undefined;
  if (!Object.hasOwn(body, 'input')) {
    errors.push({ field: 'input', message: 'is required' });
  } else if (typeof body.input !== 'string') {
    errors.push({ field: 'input', message: 'must be a string' });
  } else if (body.input.length < 1 || body.input.length > MAX_INPUT_LENGTH) {
    errors.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (body.input.trim() === '') {
    errors.push({ field: 'input', message: 'must not be blank' });
  } else {
    input = body.input;
  }

  const steps = intField(body, 'steps', DEFAULT_STEPS, 1, 20, errors);
  const failAttempts = intField(body, 'failAttempts', DEFAULT_FAIL_ATTEMPTS, 0, 5, errors);

  if (errors.length !== before || input === undefined || steps === undefined || failAttempts === undefined) return undefined;
  return { input, steps, failAttempts };
}

